<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?>
<div id="wrapper"><div class="content"><div class="panel_s"><div class="panel-body">
<div class="tw-flex tw-items-center tw-justify-between tw-flex-wrap tw-gap-2"><div><h4 class="tw-mt-0"><i class="fa fa-bell"></i> Appointment Notification Log</h4><p class="text-muted">Customer and staff appointment notices recorded by the dispatch workflow.</p></div><a href="<?php echo admin_url('appointly/smartchoice/dispatch'); ?>" class="btn btn-default btn-sm"><i class="fa fa-arrow-left"></i> Dispatch Board</a></div><hr>
<div class="table-responsive"><table class="table table-striped table-hover dt-table"><thead><tr><th>ID</th><th>Appointment</th><th>Event</th><th>Channel</th><th>Recipient</th><th>Status</th><th>Message</th><th>Sent</th></tr></thead><tbody>
<?php foreach ($logs as $log) { ?><tr><td><?php echo (int)$log['id']; ?></td><td><?php echo (int)($log['appointment_id'] ?? 0); ?></td><td><?php echo html_escape(ucwords(str_replace('-', ' ', $log['event_type'] ?? ''))); ?></td><td><?php echo html_escape(strtoupper($log['channel'] ?? '')); ?></td><td><?php echo html_escape($log['customer_email'] ?? (!empty($log['staff_id']) ? get_staff_full_name($log['staff_id']) : '-')); ?></td><td><span class="label label-<?php echo ($log['status'] ?? '') === 'sent' ? 'success' : 'warning'; ?>"><?php echo html_escape($log['status'] ?? ''); ?></span></td><td><?php echo html_escape($log['message'] ?? ''); ?></td><td><?php echo !empty($log['sent_at']) ? _dt($log['sent_at']) : _dt($log['created_at']); ?></td></tr><?php } ?>
</tbody></table></div></div></div></div></div><?php init_tail(); ?>
